"""Revision 1 (peer review, Cancers): build manuscript_R1.md and supplementary_R1.md from the submitted markdown.
Usage: python3 -I revise_R1.py manuscript_submitted.md A5_reviewer_analyses.json TableS1_A2.md manuscript_R1.md supplementary_R1.md "<title>"
Citations are held as tokens [@n] (n = number in the submitted reference list) or [@Key] (new references) and renumbered by first appearance."""
import sys, re, json
SRC, A5J, TS1, OUTM, OUTS, TITLE = sys.argv[1:7]
L = open(SRC, encoding="utf8").read().split("\n")
A = json.load(open(A5J))
iref = L.index("## References")

# ---------------------------------------------------------------- citations -> tokens
def tok(m):
    ids = []
    for part in m.group(1).split(","):
        part = part.strip()
        if "–" in part:
            a, b = part.split("–"); ids += list(range(int(a), int(b) + 1))
        else: ids.append(int(part))
    return "[" + ",".join(f"@{i}" for i in ids) + "]"
CIT = re.compile(r"\\\[(\d+(?:[–,]\s?\d+)*)\\\]")
body = [CIT.sub(tok, x) for x in L[:iref]]
REFS = {}
for x in L[iref + 1:]:
    m = re.match(r"^(\d+)\.\s+(.*)$", x)
    if m: REFS[m.group(1)] = m.group(2)
REFS["Cheng"] = "Cheng, X.; Liu, Y.; Wang, J.; Chen, Y.; Robertson, A.G.; Zhang, X.; et al. cSurvival: A Web Resource for Biomarker Interactions in Cancer Outcomes and in Cell Lines. *Brief. Bioinform.* **2022**, *23*, bbac090. https://doi.org/10.1093/bib/bbac090"
REFS["Majd"] = "Majd, E.; Xing, L.; Zhang, X. Segmentation of Patients with Small Cell Lung Cancer into Responders and Non-Responders Using the Optimal Cross-Validation Technique. *BMC Med. Res. Methodol.* **2024**, *24*, 83. https://doi.org/10.1186/s12874-024-02185-7"
REFS["Dong"] = "Dong, Y.; Ai, H.; Yao, S.; Cao, X.; Li, K.; Dong, Y.; Zhang, X. Graph Contrastive Learning for Inferring Spatial Cell Composition from Integrated Single-Cell RNA Sequencing and Spatial Transcriptomics. *IEEE J. Biomed. Health Inform.* **2026**, 1–13. https://doi.org/10.1109/JBHI.2026.3701789"
REFS["DiLeva"] = "Di Leva, G.; Gasparini, P.; Piovan, C.; Ngankeu, A.; Garofalo, M.; Taccioli, C.; et al. MicroRNA Cluster 221-222 and Estrogen Receptor α Interactions in Breast Cancer. *J. Natl. Cancer Inst.* **2010**, *102*, 706–721. https://doi.org/10.1093/jnci/djq102"
assert REFS["40"].startswith("Zhao")
REFS["Zhang"] = "Zhang, X.; Zhao, Q.; Chen, C.; Moa, B.; Gao, S. Bayesian Adaptive Design for Clinical Trials with Potential Subgroup Effects. *Stat. Methods Med. Res.* **2026**, *35*, 1395–1407. https://doi.org/10.1177/09622802261449368"

f1 = lambda x: f"{100 * x:.1f}"
def kn(v): return f"{v[0]} ({f1(v[2])}%)"
def knci(v): return f"{v[0]} ({f1(v[2])}%; {f1(v[3])}–{f1(v[4])})"
R1, R2, R3, R4, R5, R6, R7, R8 = (A[k] for k in ("R1", "R2", "R3", "R4", "R5", "R6", "R7", "R8"))
auc = lambda y, f: f"{R2['auc'][y][f]['mean']:.2f}"
aucr = lambda y, f: f"{R2['auc'][y][f]['mean']:.2f} (range {R2['auc'][y][f]['range'][0]:.2f}–{R2['auc'][y][f]['range'][1]:.2f})"
S5, G5 = R5["scanb"], R5["gse25066"]

NEW = {}          # 1-indexed line number of the submitted file -> replacement text (None = delete)
def setl(n, text): NEW[n] = text
def dele(a, b):
    for n in range(a, b + 1): NEW[n] = None

setl(1, "# " + TITLE)
setl(3, "**Article type:** Article (reproducibility and agreement study; secondary analysis of public data)")
setl(17, "Hormone therapy for breast cancer is offered when a tissue stain shows the oestrogen receptor. Tumours with a negative stain are not offered it. Gene-activity data sometimes suggest that the receptor is still at work in a stain-negative tumour; we call this \"hidden activity\". We tested how dependable that label is before anyone relies on it, using public data from 3273 Swedish tumours and a second set of 508 tumours. The two gene-activity measurements behind the label were highly repeatable when the same sample was sequenced twice. The label itself was not stable. About 1 in 12 stain-negative tumours carried it in the Swedish data and about 1 in 5 in the second set, and the number changed several-fold with the cut-off chosen. The labelled tumours were a mixed group. The label is a research finding, not yet a dependable test result. This study did not examine treatment or survival.")
setl(21, "**Background/Objectives:** Transcriptomic oestrogen-receptor (ER) activity has been proposed to identify immunohistochemically (IHC) ER-negative breast cancers with ER-related transcription. We audited whether such a \"hidden ER activity\" (HEA) call is repeatable, how it depends on definition and cohort, and what it captures.")
setl(23, "**Methods:** Reproducibility and agreement study of public data. In SCAN-B (GSE96058; RNA sequencing; 3273 tumours, 136 replicate pairs), IHC ER-negative tumours (n = 241) were called HEA when ESR1 expression and an oestrogen-response score omitting ESR1 both reached the 5th percentile of IHC ER-positive tumours. The plan was not publicly registered. An external cohort (GSE25066; microarray; 205 IHC ER-negative tumours) and analyses requested in peer review were post hoc.")
setl(25, f"**Results:** HEA was called in 20/241 SCAN-B tumours (8.3%, 95% CI 5.4–12.5). Measurements were highly repeatable (intraclass correlation ≥0.99), and the joint call agreed in 135/136 replicate pairs. No HEA tumour had a replicate, so HEA-call stability rests on simulation. The count was {S5['counts']['2.5'][0]}, 20 and {S5['counts']['10'][0]} at the 2.5th, 5th and 10th percentiles ({S5['counts']['1'][0]} at the 1st). HEA tumours were mixed (10/20 PAM50 luminal, 6/20 Normal-like). Expression-derived summaries predicted the call (AUC {auc('HEA','expression_derived_only')}); processing metadata did so weakly ({auc('HEA','metadata_only')}). In GSE25066, HEA was called in 39/205 tumours (19.0%, 14.2–24.9). On a common gene set with matched reference groups, the difference from SCAN-B was {f1(R4['by_percentile']['5']['diff_gse_minus_scanb'][0])} percentage points ({f1(R4['by_percentile']['5']['diff_gse_minus_scanb'][1])}–{f1(R4['by_percentile']['5']['diff_gse_minus_scanb'][2])}).")
setl(27, "**Conclusions:** The measurements are repeatable, but the HEA label depends on threshold, definition and cohort and is heterogeneous. It is a descriptive label, not evidence of functional ER signalling, and needs protein-level, functional and outcome validation.")
setl(29, "**Keywords:** breast neoplasms; oestrogen receptor alpha; ESR1; immunohistochemistry; RNA-seq; reproducibility; classification threshold; external validation; androgen receptor; SCAN-B")

# ---- Introduction
setl(33, "Oestrogen-receptor (ER) status, assessed by immunohistochemistry (IHC), is the main predictive biomarker for endocrine therapy in breast cancer. Since the 2010 ASCO/CAP guideline, tumours with at least 1% ER-stained invasive cells have been classified as ER-positive, and the 2020 update introduced an \"ER-low\" category for 1–10% staining [@1]. The cut-off is not uniform: Swedish guidelines define ER positivity as at least 10% stained cells [@24]. ER-low tumours account for an estimated 2–7% of breast cancers and resemble ER-negative disease in their clinicopathological features, molecular and immune profile and response to chemotherapy [@2,@3,@4,@9,@12]. Whether they benefit from endocrine therapy remains uncertain. A meta-analysis of six retrospective studies (8765 patients) associated endocrine therapy with better overall survival (hazard ratio 0.81), but the evidence is observational [@5,@6]. In a nationwide Swedish cohort of 75,211 HER2-negative patients, tumours with 10–29% ER staining had survival and molecular characteristics similar to ER-low and ER-zero tumours, which supports reporting ER as a percentage rather than a binary call [@7]. Tumours below 1% are ER-negative and are managed as triple-negative breast cancer (TNBC) when HER2 is also negative.")
setl(35, "IHC is a protein measurement with known pre-analytical and interpretive variability. Tumours near the positivity threshold behave heterogeneously [@8,@9,@10,@11]: repeat staining and RNA-based assays reclassify a substantial fraction of ER-low tumours as ER-negative [@10], and the response to endocrine therapy rises with quantitative ER expression [@11]. In the Swedish population-based SCAN-B cohort, ER-low/HER2-negative tumours were transcriptionally part of TNBC, apart from a minority of borderline cases with luminal features [@13]. Swedish real-world data show that ER-low HER2-negative tumours treated as TNBC have outcomes similar to ER-zero disease [@14].")
setl(41, body[40].replace("express FOXA1- and AR-driven luminal programmes without ESR1", "express luminal programmes associated with FOXA1 and AR without ESR1"))
dele(43, 44)
setl(45, "We therefore audited the HEA label in public data. This is a reproducibility and agreement study. It does not seek new biological mechanisms, and its results are descriptive. Earlier work showed that RNA-sequencing classifiers reproduce IHC ER status in SCAN-B with a small number of discordant tumours [@21,@22,@23], and described the transcriptional heterogeneity of ER-low and ER-zero tumours [@13]. Those studies did not examine how stable the IHC-negative, RNA-positive label itself is. We asked four questions about it: whether the measurements behind the label are repeatable; how much the number of HEA tumours changes with the threshold and with the definition; what kinds of tumour carry the label; and whether the findings hold in a second cohort.\n\nTwo datasets were used for these questions. The main cohort was the population-based SCAN-B RNA-sequencing series (GSE96058), which includes technical replicates. The external cohort was a microarray series of pre-treatment biopsies (GSE25066 [@47]), added after co-author review. Four further small datasets (two microRNA and two cell-line datasets) were examined only as exploratory background on mechanisms of ER silencing. They do not test HEA tumours and are reported in the Supplementary Materials (Supplementary Note S1).\n\nThe relevance of such an audit is analytical. Before a marker is tested for clinical validity or utility, its measurement and its classification rule need to be shown to be stable [@49]. This is not a prognostic or predictive marker study. No survival or treatment-effect claims are made, and the results cannot show whether HEA tumours respond to endocrine therapy.")

# ---- Methods
setl(51, "This is a reproducibility and agreement study that uses publicly available, de-identified data (a secondary analysis). It is reported following the Guidelines for Reporting Reliability and Agreement Studies (GRRAS) [@48], with the applicable items of the REMARK guidelines [@49]. Only six datasets were analysed. Two were used for the main questions (Table 1). Four were used for exploratory background and are described in Supplementary Note S1 and Table S3.")
setl(55, "**Table 1.** Datasets used for the main analyses. The four datasets used for exploratory background are listed in Table S3.")
setl(57, "| Accession | Material | Platform | Samples used | IHC ER status | Role |")
setl(58, "| --- | --- | --- | --- | --- | --- |")
setl(59, "| GSE96058 (SCAN-B) [@21] | Primary breast tumours (surgical specimens), Sweden | RNA-seq (Illumina HiSeq 2000 and NextSeq 500) | 3273 tumours + 136 technical replicates | Binary clinical value; cut-off of the deposited field not stated (Swedish standard ≥10%; Section 2.2) | Main cohort |")
setl(60, "| GSE25066 [@47] | Pre-treatment biopsies of HER2-negative breast cancer from four contributing centres or trial groups | Affymetrix HG-U133A microarray (GPL96) | 508 tumours: 205 IHC ER-negative, 297 IHC ER-positive, 6 indeterminate or missing | Binary; assessed locally; any nuclear staining counted for endocrine eligibility in the source study (Section 2.7) | External cohort (post hoc) |")
dele(61, 64)
setl(66, "An internal analysis plan was written and its SHA-256 hash recorded (889f096c…f843; 25 October 2026, 01:39 UTC) before any score was computed or any outcome was viewed. The survival variables were moved to a separate locked file when the data were loaded and were opened only after the hash was recorded. A dated amendment (A1; SHA-256 3fa02b5b…ded8) was committed before the composition-adjusted analysis and the exploratory background analyses. Four later amendments (A2–A5) cover post hoc analyses and are described below. The plan and amendments A1–A4 were not registered or posted publicly before the analyses were run, so readers cannot verify their timing independently. The words \"planned\" and \"post hoc\" in this article therefore describe the authors' own record. Amendment A5, which covers the analyses requested in peer review, was pushed with its hash to the public repository before those analyses were run. Deviations and exploratory additions were logged with dates and are identified as such below.")
setl(70, body[69] + " Swedish clinical practice defines ER positivity as at least 10% stained tumour cells [@24]. The classifier-training set of the source study was scored at 1% or more, and that study reports similar results for the present cohort at the 10% cut-off [@21]. The cut-off behind the deposited binary field is not stated in the GEO record. The IHC ER-negative group analysed here may therefore include ER-low tumours (1–9% staining) as well as ER-zero tumours.")
setl(76, "The ESR1 axis was the log2 expression of ESR1. The primary ER-activity score was a single-sample rank score [@53]. Within each sample, genes with a median log2 expression above 0 across unique tumours (13,750 genes) were ranked and the ranks scaled to 0–1. The score was the mean scaled rank of the genes in the MSigDB Hallmark Estrogen Response Early and Late sets (v7.0) [@54], with ESR1 removed so that ESR1 itself does not contribute to the activity score (276 genes). The two axes are not statistically independent (Section 3.4). Planned secondary scores were the same rank score for the Early set only (188 genes) and the Late set only (183 genes), and the mean per-gene z-score of five canonical ER targets (PGR, GREB1, TFF1, PDZK1, MYB).")
setl(78, "A tumour was \"high\" on an axis if its value was at or above the 5th percentile of the same measure among IHC ER-positive tumours. The 5th percentile was written into the analysis plan before any score was computed, as a conventional lower bound of the reference distribution. It was not tuned against any count or outcome, and it is arbitrary. The plan named the 1st and 10th percentiles as sensitivity thresholds. \"Low\" means below the reference threshold, not absent. IHC ER-negative tumours were assigned to four groups: hidden ER activity (HEA; ESR1 high, activity high), silent ESR1 (ESR1 high, activity low), activity without ESR1 (ESR1 low, activity high) and concordant ER-negative (ESR1 low, activity low; that is, negative by IHC and by both transcriptomic measures).\n\nThroughout this article, HEA means an IHC ER-negative tumour whose ESR1 expression and activity score are both at or above their reference thresholds. HEA is a descriptive transcriptomic label. It is not a measurement of ER protein or of functional ER signalling.\n\nThree kinds of comparator definition were used. The first keeps the construct and changes the signature: HEA with each secondary score in place of the primary score. The second is ESR1 high alone. The third is the pair of RNA-based ER classifiers deposited with GSE96058 [@21]. The single-gene classifier (SGC) is an ESR1 expression threshold that was chosen to maximise concordance with consensus IHC in a separate training set of 405 tumours. The multigene classifier (MGC) is a nearest-shrunken-centroid model trained on the 5000 most variable genes with the same labels; 459 genes carry non-zero weight. Both were built to predict IHC ER status, not to identify HEA, so they are different constructs from the joint definition.")
setl(80, "### 2.4. Planned Analyses")
setl(82, "The analyses in the plan were as follows.")
setl(85, "2. **Repeatability of the measurements** across the 136 replicate pairs, 36 of them sequenced on different platforms. This used the intraclass correlation coefficient (ICC; two-way, absolute agreement, single measure) with bootstrap 95% CIs (2000 resamples of pairs), together with percentage agreement and Cohen's κ for high/low calls.")
setl(90, "7. **A model planned as a technical-only negative control.** This was an L2-penalised logistic regression predicting the HEA call from two kinds of feature: processing metadata (sequencing platform and library tokens from the SCAN-B sample identifiers) and summaries derived from the expression matrix (the fraction of genes above the expression floor, median ribosomal-protein gene expression and mean expression across all genes). Performance was estimated by nested cross-validation (outer stratified 5-fold repeated 20 times; inner 5-fold tuning of the penalty). A ridge regression for the continuous activity score was fitted in the same way. In the submitted version, features were standardised on each outer training fold before the inner tuning. In this revision the penalty was tuned by an inner grid search over a pipeline, so that standardisation is fitted inside each inner training fold (amendment A5). All values reported here come from the corrected procedure unless marked.")
setl(91, "8. **A check for a normal-tissue-like signal:** the proportion of PAM50 Normal-like tumours, and a normal/adipose proxy (mean z-score of ADIPOQ, PLIN1, LEP and CIDEA), compared between HEA and concordant ER-negative tumours.")
setl(94, "PAM50 calls were taken as deposited [@21,@55,@56]. The plan specified a mitochondrial-read feature for analysis 7, but the deposited matrix contains no mitochondrially encoded genes, so this feature was dropped (logged before any model was fitted). After the model of analysis 7 gave an AUC above 0.5, four exploratory checks were added: a label-permutation null (200 permutations), a refit excluding PAM50 Normal-like tumours, univariate AUCs of each feature, and the association of mean expression with subtype.")
setl(96, "Outcome data were reported only as counts per group: patients, deaths, median follow-up (reverse Kaplan–Meier) and treatment. Hazard ratios and survival comparisons were not computed, as planned, because the groups were too small to be informative.")
setl(100, body[99] + " These scores are indirect. They index stromal and immune signal, not the fraction of tumour cells, and they do not measure normal epithelium.")
setl(106, body[105].replace("left every pre-specified analysis, threshold and group unchanged", "left every planned analysis, threshold and group unchanged"))
setl(109, "- **Stability near the thresholds.** A value was defined as near-threshold when it lay within two replicate-derived technical standard deviations (SDs) of its threshold. One SD was 0.266 log2 units for ESR1 and 0.0022 for the activity score, so the zone was ±0.53 log2 units and ±0.0044. Call agreement in replicate pairs was compared inside and outside this zone, and reclassification probabilities were summarised for near-threshold IHC ER-negative tumours.")
setl(110, body[109].replace("**Splitting the technical-only model.** The technical-only model was refitted", "**Splitting the model of analysis 7 by component.** The model was refitted"))
setl(121, "- **Thresholds.** Thresholds were re-anchored to the 5th percentile (1st and 10th as alternatives) of each measure among the cohort's own IHC ER-positive tumours. SCAN-B thresholds were not transferred, because the platforms differ. The external analysis therefore evaluates a cohort-relative procedure. It does not test the transport of a fixed classifier.")
setl(123, body[122] + " The threefold rule had no external justification. It is reported as written, but the interpretation does not rely on it.")
A5TXT = f"""### 2.8. Analyses Requested in Peer Review (Amendment A5)

The reviewers of the submitted version requested further analyses. They were specified in a fifth amendment (A5; SHA-256 97831068…01e6; 24 November 2026, 22:34 UTC), which was pushed to the public repository before any of them was run. All are post hoc. No pass or fail rule was attached to them, and an interval for a difference that contains zero is not read as equivalence. Full results are in Table S2.

- **Observed agreement of the joint call.** For all 136 replicate pairs, of any IHC status, agreement and Cohen's κ of the joint \"both high\" call; and the same for pairs whose original library lay inside the range of the 20 HEA tumours on both axes.
- **The model of analysis 7 by feature type.** The model was fitted with all features, with processing metadata only, and with expression-derived summaries only, for the HEA call, ESR1-high, activity-high, the composition-adjusted HEA call and the continuous activity score, using the corrected cross-validation.
- **Bounds for missing IHC ER status.** HEA prevalence was recomputed under two extreme assumptions about the 200 tumours without an ER result: that every such tumour above both thresholds was ER-positive and every other one ER-negative; and the reverse.
- **Common gene universe and matched reference group.** Both cohorts were restricted to the genes present in both (the SCAN-B ranking background and the GSE25066 gene table), ranks were recomputed, and one identical signature gene list was used. For the comparison with GSE25066, which is HER2-negative by design, the SCAN-B thresholds were taken from HER2-negative IHC ER-positive tumours.
- **Operating thresholds and threshold uncertainty.** The primary definition was applied at the 1st, 2.5th, 5th, 7.5th and 10th percentiles in both cohorts. The IHC ER-positive reference was resampled with replacement (2000 times) to give intervals for the thresholds and for the HEA count among the fixed IHC ER-negative tumours; resampling both groups gave an interval for prevalence that includes threshold uncertainty.
- **Dependence between the two axes.** Spearman correlation between ESR1 and the activity score, with bootstrap 95% CIs.
- **Reclassification with uncertain thresholds and noise.** The simulations of analysis 3 and of amendment A3 were repeated inside a bootstrap (500 resamples, 2000 draws each) in which the replicate pairs and the IHC ER-positive reference were resampled, so that the technical SDs, their correlation and the thresholds were re-estimated each time.
- **Two-group bootstrap** for the difference in the normal/adipose proxy, replacing an interval in which only the HEA group had been resampled.
"""
setl(125, A5TXT.rstrip("\n") + "\n")
