# ---------------------------------------------------------------- renumber
TOK = re.compile(r"\[(@[\w]+(?:,@[\w]+)*)\]")
def renumber(text, label=""):
    order = []
    for m in TOK.finditer(text):
        for k in m.group(1).split(","):
            k = k[1:]
            if k not in order: order.append(k)
    num = {k: i + 1 for i, k in enumerate(order)}
    def fmt(m):
        ns = sorted({num[k[1:]] for k in m.group(1).split(",")}); parts = []; i = 0
        while i < len(ns):
            j = i
            while j + 1 < len(ns) and ns[j + 1] == ns[j] + 1: j += 1
            parts.append(str(ns[i]) if j == i else (f"{ns[i]},{ns[j]}" if j == i + 1 else f"{ns[i]}–{ns[j]}")); i = j + 1
        return "\\[" + ",".join(parts) + "\\]"
    return TOK.sub(fmt, text), order
